class FakeRTC{constructor(){this.id=++nextPC;pcs.set(this.id,this);this.channels=[];this.localDescription=null;this.remoteDescription=null;this.iceGatheringState='complete';this.signalingState='stable';this.connectionState='new'}createDataChannel(label){const c=new Channel(label);this.channels.push(c);return c}async createOffer(){return {type:'offer',sdp:JSON.stringify({id:this.id})}}async createAnswer(){return {type:'answer',sdp:JSON.stringify({id:this.id,host:this.host.id})}}async setLocalDescription(d){this.localDescription=d;this.signalingState=d.type==='offer'?'have-local-offer':'stable'}async setRemoteDescription(d){this.remoteDescription=d;if(d.type==='offer'){this.host=pcs.get(JSON.parse(d.sdp).id);this.signalingState='have-remote-offer'}else{const guest=pcs.get(JSON.parse(d.sdp).id);for(const h of this.channels){const g=new Channel(h.label);g.other=h;h.other=g;guest.channels.push(g);guest.ondatachannel?.({channel:g})}this.signalingState='stable';queueMicrotask(()=>{for(const p of [this,guest]){p.connectionState='connected';for(const c of p.channels)c.readyState='open';p.onconnectionstatechange?.()}for(const p of [this,guest])for(const c of p.channels)c.onopen?.()})}}addEventListener(){}removeEventListener(){}close(){this.connectionState='closed';for(const c of this.channels)c.close();this.onconnectionstatechange?.()}}
