const roomPeers=new Map();let roomAuto=0;
class RoomEvents{constructor(){this.events={}}on(name,fn){(this.events[name]??=[]).push(fn);return this}emit(name,value){for(const fn of this.events[name]||[])fn(value)}}
class FakeRoomConnection extends RoomEvents{constructor(label){super();this.label=label;this.open=false;this.dataChannel={bufferedAmount:0};this.closed=false}send(packet){if(!this.open)throw Error('closed');const copy=JSON.parse(JSON.stringify(packet));queueMicrotask(()=>{if(this.other?.open)this.other.emit('data',copy)})}close(){if(this.closed)return;this.closed=true;this.open=false;queueMicrotask(()=>this.emit('close'));this.other?.close()}}
class FakeRoomPeer extends RoomEvents{constructor(id){super();this.id=id||'guest-'+(++roomAuto);this.links=[];this.destroyed=false;queueMicrotask(()=>{if(this.destroyed)return;if(roomPeers.has(this.id)){this.emit('error',{type:'unavailable-id'});return}roomPeers.set(this.id,this);this.emit('open',this.id)})}connect(id,options){const c=new FakeRoomConnection(options.label);this.links.push(c);queueMicrotask(()=>{const remote=roomPeers.get(id);if(!remote){this.emit('error',{type:'peer-unavailable'});return}const other=new FakeRoomConnection(options.label);c.other=other;other.other=c;remote.links.push(other);remote.emit('connection',other);queueMicrotask(()=>{if(c.closed||other.closed)return;c.open=other.open=true;other.emit('open');c.emit('open')})});return c}destroy(){if(this.destroyed)return;this.destroyed=true;if(roomPeers.get(this.id)===this)roomPeers.delete(this.id);for(const c of this.links)c.close()}}

